'use client';

import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import {
  ShieldCheck,
  ShieldAlert,
  Mail,
  AlertTriangle,
  Send,
  Activity,
  CheckCircle,
  Clock,
  Settings as SettingsIcon,
  RefreshCw,
} from 'lucide-react';
import { AccountHealth, Settings } from '@/types';

export default function Accounts() {
  const [accounts, setAccounts] = useState<AccountHealth[]>([]);
  const [settings, setSettings] = useState<Settings | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newAccount, setNewAccount] = useState({ email: '', password: '', smtpHost: '', imapHost: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleAddAccount = async () => {
    if (!newAccount.email || !newAccount.password || !newAccount.smtpHost || !newAccount.imapHost) {
      setError('Please fill in all fields.');
      return;
    }
    setIsSubmitting(true);
    try {
      const res = await fetch('/api/accounts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newAccount)
      });
      if (!res.ok) throw new Error('Failed to save account');
      await loadData();
      setShowAddModal(false);
      setNewAccount({ email: '', password: '', smtpHost: '', imapHost: '' });
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteAccount = async (id: string) => {
    if (!confirm('Are you sure you want to delete this mailbox?')) return;
    try {
      const res = await fetch(`/api/accounts?id=${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to delete account');
      await loadData();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const loadData = async () => {
    setRefreshing(true);
    try {
      const [accountsRes, settingsRes] = await Promise.all([
        fetch('/api/accounts'),
        fetch('/api/settings'),
      ]);

      if (!accountsRes.ok || !settingsRes.ok) {
        throw new Error('Failed to load accounts metadata');
      }

      const accountsData = await accountsRes.json();
      const settingsData = await settingsRes.json();

      setAccounts(accountsData);
      setSettings(settingsData);
      setError(null);
    } catch (err: any) {
      setError(err.message || 'Error loading accounts dashboard data.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 10000);
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] p-10 max-w-lg mx-auto text-center font-sans">
        <div className="relative w-16 h-16 mb-6">
          <motion.div
            animate={{ rotate: 360 }}
            transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}
            className="w-16 h-16 rounded-full border-4 border-[var(--border-default)] border-t-[var(--honey-500)]"
          />
        </div>
        <h2 className="text-xl font-bold text-[var(--text-secondary)]">Evaluating Mailbox Health...</h2>
      </div>
    );
  }

  const dailyLimit = typeof settings?.maxEmailsPerDay === 'number' ? settings.maxEmailsPerDay : 30;
  const criticalAccountsCount = accounts.filter(a => a.healthScore === 'critical').length;
  const warningAccountsCount = accounts.filter(a => a.healthScore === 'warning' || a.bounceRate > 0.03).length;

  const formatDate = (timestamp: number | null) => {
    if (!timestamp) return 'Never active';
    return new Date(timestamp).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getScoreBadge = (score: 'good' | 'warning' | 'critical', rate: number) => {
    if (score === 'critical') {
      return (
        <span className="flex items-center gap-1 text-[10px] font-bold text-[var(--danger)] bg-[var(--danger-bg)] border border-red-500/10 px-2 py-0.5 rounded-full uppercase tracking-wider">
          <ShieldAlert size={10} /> Critical
        </span>
      );
    }
    if (score === 'warning' || rate > 0.03) {
      return (
        <span className="flex items-center gap-1 text-[10px] font-bold text-[var(--warning)] bg-[var(--warning-bg)] border border-amber-500/10 px-2 py-0.5 rounded-full uppercase tracking-wider">
          <ShieldAlert size={10} /> Warning
        </span>
      );
    }
    return (
      <span className="flex items-center gap-1 text-[10px] font-bold text-[var(--success)] bg-[var(--success-bg)] border border-emerald-500/10 px-2 py-0.5 rounded-full uppercase tracking-wider">
        <ShieldCheck size={10} /> Good Health
      </span>
    );
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 font-sans">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-extrabold text-[var(--text-primary)] tracking-tight font-serif">Outreach Mailboxes</h1>
          <p className="text-[var(--text-secondary)] text-sm mt-1">Manage SMTP/IMAP rotation accounts, bounce thresholds, and warmups.</p>
        </div>
        <button
          onClick={loadData}
          disabled={refreshing}
          className="p-2.5 rounded-xl bg-[var(--bg-surface)] border border-[var(--border-default)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--honey-50)] transition-all active:scale-95 disabled:opacity-50 cursor-pointer"
          title="Refresh Accounts"
          aria-label="Refresh Accounts"
        >
          <RefreshCw size={18} className={refreshing ? 'animate-spin' : ''} />
        </button>
      </div>

      {error && (
        <div className="glass-panel border-[var(--danger)]/20 bg-[var(--danger-bg)] p-4 rounded-xl flex items-center gap-3 text-[var(--danger)] text-sm font-semibold">
          <AlertTriangle size={18} className="shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {/* Warning Banners */}
      {warningAccountsCount > 0 && (
        <div className="glass-panel border-[var(--warning)]/20 bg-[var(--warning-bg)] p-5 rounded-2xl flex items-start gap-4">
          <div className="p-2 bg-[var(--bg-surface)] rounded-xl border border-[var(--warning)]/20 text-[var(--warning)]">
            <AlertTriangle size={20} />
          </div>
          <div>
            <h4 className="text-sm font-bold text-[var(--text-primary)]">Outreach Health Notice</h4>
            <p className="text-[var(--text-secondary)] text-xs mt-1 leading-relaxed">
              There are {warningAccountsCount} mailboxes with a bounce rate exceeding 3.0%. 
              To protect domain reputation and avoid ISP rate-limiting, we recommend auditing the lead validation settings.
            </p>
          </div>
        </div>
      )}

      {criticalAccountsCount > 0 && (
        <div className="glass-panel border-[var(--danger)]/20 bg-[var(--danger-bg)] p-5 rounded-2xl flex items-start gap-4">
          <div className="p-2 bg-[var(--bg-surface)] rounded-xl border border-[var(--danger)]/20 text-[var(--danger)] animate-pulse">
            <ShieldAlert size={20} />
          </div>
          <div>
            <h4 className="text-sm font-bold text-[var(--text-primary)]">Automatic Account Auto-Pause Imminent</h4>
            <p className="text-[var(--text-secondary)] text-xs mt-1 leading-relaxed">
              {criticalAccountsCount} mailboxes have crossed the critical 5.0% bounce threshold and are auto-paused during sender worker execution. 
              Please verify/clean your leads list or update settings to prevent full campaign suspension.
            </p>
          </div>
        </div>
      )}

      {/* Accounts Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {accounts.map((account, index) => {
          const limitPct = (account.sentToday / dailyLimit) * 100;
          const bouncePct = (account.bounceRate * 100).toFixed(1);

          return (
            <motion.div
              key={account.id}
              initial={{ opacity: 0, y: 15 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
              className="card rounded-2xl p-6 relative overflow-hidden group flex flex-col justify-between h-[280px]"
            >
              {/* Account Top Row */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <div className="p-2 bg-[var(--honey-100)] border border-[var(--border-subtle)] rounded-xl text-[var(--honey-600)] group-hover:scale-105 transition-transform">
                    <Mail size={18} />
                  </div>
                  {getScoreBadge(account.healthScore, account.bounceRate)}
                </div>

                <div className="space-y-0.5">
                  <h3 className="text-sm font-bold text-[var(--text-primary)] truncate pr-6" title={account.email}>
                    {account.email}
                  </h3>
                  <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase tracking-wider">Mailbox ID: Account {account.id}</p>
                </div>
              </div>
              <button 
                onClick={() => handleDeleteAccount(String(account.id))} 
                className="absolute top-4 right-4 p-1.5 bg-[var(--danger-bg)] text-[var(--danger)] rounded-lg opacity-0 group-hover:opacity-100 transition-opacity hover:bg-[var(--danger)] hover:text-white z-10 cursor-pointer border border-[var(--danger)]/15"
                title="Delete Mailbox"
                aria-label="Delete Mailbox"
              >
                <ShieldAlert size={14} />
              </button>

              {/* Progress and Limits */}
              <div className="space-y-2 my-2">
                <div className="flex justify-between text-xs font-semibold">
                  <span className="text-[var(--text-secondary)]">Daily Limits Progress</span>
                  <span className="text-[var(--text-primary)] font-bold font-mono">{account.sentToday} / {dailyLimit} sends</span>
                </div>
                <div className="progress-track">
                  <div
                    style={{ width: `${Math.min(limitPct, 100)}%` }}
                    className="progress-fill"
                  />
                </div>
              </div>

              {/* Detailed Metrics Footer */}
              <div className="grid grid-cols-3 gap-2 border-t border-[var(--border-subtle)] pt-4 text-center">
                <div>
                  <p className="text-[9px] font-bold text-[var(--text-muted)] uppercase">Total Sent</p>
                  <p className="text-sm font-bold text-[var(--text-primary)] mt-1 flex items-center justify-center gap-1 font-mono">
                    <Send size={11} className="text-[var(--text-muted)]" /> {account.totalSent}
                  </p>
                </div>
                <div>
                  <p className="text-[9px] font-bold text-[var(--text-muted)] uppercase">Bounces</p>
                  <p className={`text-sm font-bold mt-1 font-mono ${account.bounceCount > 0 ? 'text-[var(--danger)]' : 'text-[var(--text-secondary)]'}`}>
                    {account.bounceCount}
                  </p>
                </div>
                <div>
                  <p className="text-[9px] font-bold text-[var(--text-muted)] uppercase">Bounce Rate</p>
                  <p
                    className={`text-sm font-bold mt-1 font-mono ${
                      account.bounceRate > 0.05
                        ? 'text-[var(--danger)]'
                        : account.bounceRate > 0.03
                        ? 'text-[var(--warning)]'
                        : 'text-[var(--success)]'
                    }`}
                  >
                    {bouncePct}%
                  </p>
                </div>
              </div>

              {/* Last Active Timestamp */}
              <div className="flex items-center gap-1.5 text-[10px] text-[var(--text-muted)] pt-2.5 mt-2 border-t border-[var(--border-subtle)]">
                <Clock size={11} />
                <span>Last active: {formatDate(account.lastActiveAt)}</span>
              </div>
            </motion.div>
          );
        })}

        {/* Add Account Card */}
        <motion.div
          initial={{ opacity: 0, y: 15 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: accounts.length * 0.05 }}
          onClick={() => setShowAddModal(true)}
          className="card rounded-2xl p-6 hover:bg-[var(--honey-50)] border-dashed border-[var(--border-strong)] flex flex-col items-center justify-center cursor-pointer min-h-[280px]"
        >
          <div className="w-12 h-12 bg-[var(--honey-100)] rounded-full flex items-center justify-center mb-4 border border-[var(--border-default)]">
            <svg className="w-6 h-6 text-[var(--honey-600)]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" />
            </svg>
          </div>
          <h3 className="text-sm font-bold text-[var(--text-primary)]">Add New Mailbox</h3>
          <p className="text-xs text-[var(--text-muted)] mt-2 text-center">Connect a new SMTP/IMAP account for outreach.</p>
        </motion.div>
      </div>

      {showAddModal && (
        <div className="overlay flex items-center justify-center p-4 z-50">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="glass-panel-raised p-6 rounded-2xl max-w-md w-full space-y-4"
          >
            <h2 className="text-xl font-bold text-[var(--text-primary)] font-serif">Add New Mailbox</h2>
            <div className="space-y-4 font-sans">
              <div>
                <label className="block text-xs font-bold text-[var(--text-secondary)] mb-1">Email Address</label>
                <input type="email" value={newAccount.email} onChange={e => setNewAccount({...newAccount, email: e.target.value})} className="input w-full p-2.5 outline-none" placeholder="name@domain.com" />
              </div>
              <div>
                <label className="block text-xs font-bold text-[var(--text-secondary)] mb-1">App Password</label>
                <input type="password" value={newAccount.password} onChange={e => setNewAccount({...newAccount, password: e.target.value})} className="input w-full p-2.5 outline-none" placeholder="••••••••••••••••" />
              </div>
              <div>
                <label className="block text-xs font-bold text-[var(--text-secondary)] mb-1">SMTP Host</label>
                <input type="text" value={newAccount.smtpHost} onChange={e => setNewAccount({...newAccount, smtpHost: e.target.value})} className="input w-full p-2.5 outline-none" placeholder="smtp.gmail.com" />
              </div>
              <div>
                <label className="block text-xs font-bold text-[var(--text-secondary)] mb-1">IMAP Host</label>
                <input type="text" value={newAccount.imapHost} onChange={e => setNewAccount({...newAccount, imapHost: e.target.value})} className="input w-full p-2.5 outline-none" placeholder="imap.gmail.com" />
              </div>
            </div>
            <div className="flex justify-end gap-3 mt-6">
              <button onClick={() => setShowAddModal(false)} disabled={isSubmitting} className="btn btn-secondary py-2">Cancel</button>
              <button onClick={handleAddAccount} disabled={isSubmitting} className="btn btn-primary py-2">{isSubmitting ? 'Saving...' : 'Save Account'}</button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';
import { AccountHealth } from '@/types';

const settingsPath = path.resolve(process.cwd(), '../settings.json');
const campaignDbPath = path.resolve(process.cwd(), '../campaign_db.json');

function getSettings() {
  if (fs.existsSync(settingsPath)) {
    try {
      return JSON.parse(fs.readFileSync(settingsPath, 'utf8'));
    } catch {}
  }
  return {};
}

function saveSettings(settings: any) {
  fs.writeFileSync(settingsPath, JSON.stringify(settings, null, 2), 'utf8');
}

function getTodayDateString() {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Chicago',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });
  const parts = formatter.formatToParts(new Date());
  const year = parts.find(p => p.type === 'year')?.value || '2026';
  const month = parts.find(p => p.type === 'month')?.value || '06';
  const day = parts.find(p => p.type === 'day')?.value || '01';
  return `${year}-${month}-${day}`;
}

export async function GET() {
  try {
    const settings = getSettings();
    const storedAccounts = settings.accounts || [];

    let campaignData: any = { records: {}, dailyCounts: {} };
    if (fs.existsSync(campaignDbPath)) {
      try {
        campaignData = JSON.parse(fs.readFileSync(campaignDbPath, 'utf8'));
      } catch {}
    }
    if (!campaignData.records) campaignData.records = {};
    if (!campaignData.dailyCounts) campaignData.dailyCounts = {};

    const todayStr = getTodayDateString();
    const accounts: AccountHealth[] = [];

    for (const acc of storedAccounts) {
      let totalSent = 0;
      let bounceCount = 0;
      let lastActiveAt: number | null = null;
      const accountId = acc.id;

      for (const record of Object.values(campaignData.records) as any[]) {
        if (String(record.accountId) === String(accountId)) {
          if (['sent', 'followed_up_1', 'followed_up_2', 'interested', 'completed_no_interest'].includes(record.status)) {
            totalSent++;
          }
          if (record.status === 'bounced') {
            bounceCount++;
            totalSent++;
          }

          const ts = record.sentAt || record.followedUp1At || record.followedUp2At;
          if (ts && (lastActiveAt === null || ts > lastActiveAt)) {
            lastActiveAt = ts;
          }
        }
      }

      const sentToday = campaignData.dailyCounts[accountId]?.[todayStr] || 0;
      const bounceRate = totalSent > 0 ? bounceCount / totalSent : 0;

      let healthScore: 'good' | 'warning' | 'critical' = 'good';
      if (bounceRate > 0.05) {
        healthScore = 'critical';
      } else if (bounceRate > 0.03) {
        healthScore = 'warning';
      }

      accounts.push({
        id: accountId,
        email: acc.email,
        sentToday,
        totalSent,
        bounceCount,
        bounceRate,
        lastActiveAt,
        healthScore,
      });
    }

    return NextResponse.json(accounts);
  } catch (err: any) {
    console.error('Error calculating account health:', err.message);
    return NextResponse.json({ error: 'Failed to retrieve accounts health' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json();

    // Strict whitelist — only accept known fields to prevent settings.json injection
    const allowedFields = ['email', 'password', 'smtpHost', 'imapHost', 'smtpPort', 'imapPort'];
    const sanitized: {
      id?: string;
      email?: string;
      password?: string;
      smtpHost?: string;
      imapHost?: string;
      smtpPort?: string;
      imapPort?: string;
    } = {};
    for (const field of allowedFields) {
      const key = field as keyof typeof sanitized;
      if (body[field] !== undefined && typeof body[field] === 'string') {
        (sanitized as Record<string, string>)[field] = body[field].trim();
      }
    }

    if (!sanitized.email || !sanitized.password) {
      return NextResponse.json({ error: 'Email and password are required' }, { status: 400 });
    }

    const settings = getSettings();
    const accounts = settings.accounts || [];

    const newAccount = {
      id: Date.now().toString(),
      ...sanitized,
    };

    settings.accounts = [...accounts, newAccount];
    saveSettings(settings);

    // Return account without password
    const { password: _p, ...safeAccount } = newAccount;
    return NextResponse.json(safeAccount);
  } catch (err) {
    return NextResponse.json({ error: 'Failed to save account' }, { status: 500 });
  }
}

export async function DELETE(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');
    if (!id) return NextResponse.json({ error: 'Account ID required' }, { status: 400 });

    const settings = getSettings();
    if (settings.accounts) {
      settings.accounts = settings.accounts.filter((a: any) => String(a.id) !== id);
      saveSettings(settings);
    }
    return NextResponse.json({ success: true });
  } catch (err) {
    return NextResponse.json({ error: 'Failed to delete account' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

import { CampaignState } from '@/types';

const statePath = path.resolve(process.cwd(), '../campaign_state.json');

const DEFAULT_STATE: CampaignState = {
  status: 'running',
  pausedAt: null,
  pauseReason: null,
  stoppedAt: null,
};

export async function GET() {
  try {
    if (!fs.existsSync(statePath)) {
      return NextResponse.json(DEFAULT_STATE);
    }
    const data = JSON.parse(fs.readFileSync(statePath, 'utf8'));
    return NextResponse.json({
      status: data.status || 'running',
      pausedAt: data.pausedAt || null,
      pauseReason: data.pauseReason || null,
      stoppedAt: data.stoppedAt || null,
    });
  } catch (err: any) {
    console.error('Error reading campaign state:', err.message);
    return NextResponse.json(DEFAULT_STATE);
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { action, reason } = body;

    let currentState = { ...DEFAULT_STATE };
    if (fs.existsSync(statePath)) {
      try {
        currentState = JSON.parse(fs.readFileSync(statePath, 'utf8'));
      } catch {}
    }

    if (action === 'pause') {
      currentState.status = 'paused';
      currentState.pausedAt = Date.now();
      currentState.pauseReason = reason || 'Paused from dashboard';
    } else if (action === 'resume') {
      currentState.status = 'running';
      currentState.pausedAt = null;
      currentState.pauseReason = null;
      currentState.stoppedAt = null;
    } else if (action === 'stop') {
      currentState.status = 'stopped';
      currentState.stoppedAt = Date.now();
    } else {
      return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
    }

    const tempPath = statePath + '.tmp';
    fs.writeFileSync(tempPath, JSON.stringify(currentState, null, 2), 'utf8');
    fs.renameSync(tempPath, statePath);

    return NextResponse.json({ success: true, state: currentState });
  } catch (err: any) {
    console.error('Error writing campaign state:', err.message);
    return NextResponse.json({ error: 'Failed to update campaign state' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';
import { LeadRecord, BusinessDbRecord } from '@/types';
import { verifyEmail } from './verifier';

const dbPath = path.resolve(process.cwd(), '../leads_db.json');
const campaignDbPath = path.resolve(process.cwd(), '../campaign_db.json');

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1', 10);
    const limit = parseInt(searchParams.get('limit') || '50', 10);
    const statusFilter = searchParams.get('status');
    const platformFilter = searchParams.get('platform');
    const stateFilter = searchParams.get('state');
    const searchQuery = searchParams.get('search')?.toLowerCase() || '';
    const sortBy = searchParams.get('sortBy') || 'activity';
    const sortOrder = searchParams.get('sortOrder') || 'desc';

    if (!fs.existsSync(dbPath)) {
      return NextResponse.json({ records: [], total: 0, page: 1, totalPages: 0 });
    }

    let data;
    try {
      data = JSON.parse(fs.readFileSync(dbPath, 'utf8'));
    } catch {
      return NextResponse.json({ records: [], total: 0, page: 1, totalPages: 0 });
    }

    let campaignData: any = { records: {} };
    if (fs.existsSync(campaignDbPath)) {
      try {
        campaignData = JSON.parse(fs.readFileSync(campaignDbPath, 'utf8'));
      } catch {}
    }
    if (!campaignData.records) campaignData.records = {};

    let rawRecords: LeadRecord[] = [];
    if (data.businesses) {
      const businesses = data.businesses as Record<string, BusinessDbRecord>;
      rawRecords = Object.values(businesses).map((b) => {
        const campaignRecord = campaignData.records[b.email || ''];
        return {
          email: b.email,
          businessName: b.name,
          platform: b.platform,
          status: campaignRecord ? campaignRecord.status : (b.emailStatus || 'found'),
          updatedAt: b.updatedAt ? new Date(b.updatedAt).getTime() : 0,
          sentAt: campaignRecord?.sentAt,
          followedUp1At: campaignRecord?.followedUp1At,
          followedUp2At: campaignRecord?.followedUp2At,
          repliedAt: campaignRecord?.repliedAt,
          bouncedAt: campaignRecord?.bouncedAt,
          completedAt: campaignRecord?.completedAt,
          state: b.state || campaignRecord?.state || '',
          city: b.city || campaignRecord?.city || '',
          website: b.website || campaignRecord?.website || '',
        };
      });
    } else if (data.records) {
      rawRecords = Object.values(data.records as Record<string, LeadRecord>);
    }

    // Filtering
    let filteredRecords = rawRecords;
    if (statusFilter && statusFilter !== 'all') {
      filteredRecords = filteredRecords.filter((r) => {
        if (statusFilter === 'followed_up') {
          return String(r.status).startsWith('followed_up');
        }
        return r.status === statusFilter;
      });
    }

    if (platformFilter && platformFilter !== 'all') {
      filteredRecords = filteredRecords.filter((r) => r.platform?.toLowerCase() === platformFilter.toLowerCase());
    }

    if (stateFilter && stateFilter !== 'all') {
      filteredRecords = filteredRecords.filter((r) => r.state?.toLowerCase() === stateFilter.toLowerCase());
    }

    if (searchQuery) {
      filteredRecords = filteredRecords.filter((r) => {
        return (
          r.email?.toLowerCase().includes(searchQuery) ||
          r.businessName?.toLowerCase().includes(searchQuery) ||
          r.status?.toLowerCase().includes(searchQuery) ||
          r.website?.toLowerCase().includes(searchQuery) ||
          r.city?.toLowerCase().includes(searchQuery) ||
          r.state?.toLowerCase().includes(searchQuery)
        );
      });
    }

    // Dynamic Sorting
    if (sortBy === 'activity') {
      filteredRecords.sort((a: LeadRecord, b: LeadRecord) => {
        const timeA = Number(a.repliedAt || a.completedAt || a.followedUp2At || a.followedUp1At || a.sentAt || a.updatedAt || 0);
        const timeB = Number(b.repliedAt || b.completedAt || b.followedUp2At || b.followedUp1At || b.sentAt || b.updatedAt || 0);
        return sortOrder === 'desc' ? timeB - timeA : timeA - timeB;
      });
    } else {
      filteredRecords.sort((a: LeadRecord, b: LeadRecord) => {
        const valA = a[sortBy];
        const valB = b[sortBy];

        // Push null/undefined values to the bottom regardless of order
        const isNilA = valA === undefined || valA === null || valA === '';
        const isNilB = valB === undefined || valB === null || valB === '';
        if (isNilA && isNilB) return 0;
        if (isNilA) return 1;
        if (isNilB) return -1;

        if (typeof valA === 'string' && typeof valB === 'string') {
          const comp = valA.localeCompare(valB, undefined, { sensitivity: 'base', numeric: true });
          return sortOrder === 'desc' ? -comp : comp;
        } else {
          const numA = Number(valA);
          const numB = Number(valB);
          return sortOrder === 'desc' ? numB - numA : numA - numB;
        }
      });
    }

    const total = filteredRecords.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const paginatedRecords = filteredRecords.slice(startIndex, startIndex + limit);

    return NextResponse.json({
      records: paginatedRecords,
      total,
      page,
      totalPages,
    });
  } catch (err: any) {
    console.error('Error getting leads:', err.message);
    return NextResponse.json({ error: 'Failed to read leads' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const { action, emails } = await request.json();

    if (!action || !emails || !Array.isArray(emails) || emails.length === 0) {
      return NextResponse.json({ error: 'Invalid payload' }, { status: 400 });
    }

    let campaignData: any = { records: {}, unsubscribed: [], activityLog: [] };
    if (fs.existsSync(campaignDbPath)) {
      try {
        campaignData = JSON.parse(fs.readFileSync(campaignDbPath, 'utf8'));
      } catch {}
    }

    if (!campaignData.records) campaignData.records = {};
    if (!campaignData.unsubscribed) campaignData.unsubscribed = [];
    if (!campaignData.activityLog) campaignData.activityLog = [];

    const now = Date.now();

    if (action === 'verify') {

      const results = [];
      for (const email of emails) {
        const normalizedEmail = email.toLowerCase().trim();
        const res = await verifyEmail(normalizedEmail);
        results.push({ email: normalizedEmail, ...res });

        if (!res.valid) {
          // Auto-mark as bounced in campaign database
          const oldRecord = campaignData.records[normalizedEmail] || {};
          const oldStatus = oldRecord.status || null;
          const newStatus = 'bounced';

          campaignData.records[normalizedEmail] = {
            ...oldRecord,
            email: normalizedEmail,
            status: newStatus,
            bouncedAt: now,
            updatedAt: now,
          };

          if (oldStatus !== newStatus) {
            campaignData.activityLog.push({
              email: normalizedEmail,
              from: oldStatus,
              to: newStatus,
              at: now,
            });
          }
        }
      }

      // Save campaign database atomically
      const tempPath = campaignDbPath + '.tmp';
      fs.writeFileSync(tempPath, JSON.stringify(campaignData, null, 2), 'utf8');
      fs.renameSync(tempPath, campaignDbPath);

      return NextResponse.json({ success: true, results });
    }

    for (const email of emails) {
      const normalizedEmail = email.toLowerCase().trim();

      if (action === 'unsubscribe') {
        if (!campaignData.unsubscribed.includes(normalizedEmail)) {
          campaignData.unsubscribed.push(normalizedEmail);
        }

        const oldRecord = campaignData.records[normalizedEmail] || {};
        const oldStatus = oldRecord.status || null;
        const newStatus = 'completed_no_interest';

        campaignData.records[normalizedEmail] = {
          ...oldRecord,
          email: normalizedEmail,
          status: newStatus,
          updatedAt: now,
        };

        if (oldStatus !== newStatus) {
          campaignData.activityLog.push({
            email: normalizedEmail,
            from: oldStatus,
            to: newStatus,
            at: now,
          });
        }
      } else if (action === 'mark_interested') {
        const oldRecord = campaignData.records[normalizedEmail] || {};
        const oldStatus = oldRecord.status || null;
        const newStatus = 'interested';

        campaignData.records[normalizedEmail] = {
          ...oldRecord,
          email: normalizedEmail,
          status: newStatus,
          repliedAt: now,
          updatedAt: now,
        };

        if (oldStatus !== newStatus) {
          campaignData.activityLog.push({
            email: normalizedEmail,
            from: oldStatus,
            to: newStatus,
            at: now,
          });
        }
      }
    }

    // Save campaign database atomically
    const tempPath = campaignDbPath + '.tmp';
    fs.writeFileSync(tempPath, JSON.stringify(campaignData, null, 2), 'utf8');
    fs.renameSync(tempPath, campaignDbPath);

    return NextResponse.json({ success: true, count: emails.length });
  } catch (err: any) {
    console.error('Error executing bulk action:', err.message);
    return NextResponse.json({ error: 'Failed to execute bulk action' }, { status: 500 });
  }
}

import { promises as dns } from 'dns';

const DNS_TIMEOUT_MS = 5000;

const DISPOSABLE_DOMAINS = [
  'mailinator.com',
  'guerrillamail.com',
  'guerrillamail.de',
  'guerrillamail.net',
  'tempmail.com',
  'throwaway.email',
  'yopmail.com',
  'sharklasers.com',
  'grr.la',
  'guerrillamailblock.com',
  'pokemail.net',
  'spam4.me',
  'trashmail.com',
  'trashmail.me',
  'trashmail.net',
  'dispostable.com',
  'mailnesia.com',
  'maildrop.cc',
  'fakeinbox.com',
  'tempail.com',
  'temp-mail.org',
  'temp-mail.io',
  'mohmal.com',
  'getnada.com',
  'emailondeck.com',
  'mintemail.com',
  'harakirimail.com',
  'jetable.org',
  'mytemp.email',
  'safetymail.info',
  'filzmail.com',
  '10minutemail.com',
  'tempinbox.com',
  'mailcatch.com',
  'meltmail.com',
  'fakeinbox.com', // duplicate in original, kept for safety
];

const ROLE_PREFIXES = [
  'noreply@',
  'no-reply@',
  'donotreply@',
  'do-not-reply@',
  'mailer-daemon@',
  'postmaster@',
  'postmaster@', // duplicate in original
];

function isValidSyntax(email: string) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

function isDisposableDomain(domain: string) {
  return DISPOSABLE_DOMAINS.includes(domain.toLowerCase());
}

function isRoleBasedEmail(email: string) {
  const lower = email.toLowerCase();
  return ROLE_PREFIXES.some(prefix => lower.startsWith(prefix));
}

async function hasValidMxRecord(domain: string) {
  try {
    const mxLookup = dns.resolveMx(domain);
    const timeout = new Promise<any[]>((_, reject) => {
      setTimeout(() => reject(new Error('DNS lookup timed out')), DNS_TIMEOUT_MS);
    });

    const records = await Promise.race([mxLookup, timeout]);
    return records && records.length > 0;
  } catch (err) {
    return false;
  }
}

async function verifyEmail(email: string) {
  if (!email || typeof email !== 'string') {
    return { valid: false, reason: 'Empty or invalid type' };
  }

  const cleanEmail = email.toLowerCase().trim();

  if (!isValidSyntax(cleanEmail)) {
    return { valid: false, reason: 'Invalid syntax' };
  }

  if (isRoleBasedEmail(cleanEmail)) {
    return { valid: false, reason: 'Role-based email address' };
  }

  const parts = cleanEmail.split('@');
  const domain = parts[1];

  if (isDisposableDomain(domain)) {
    return { valid: false, reason: `Disposable email domain: ${domain}` };
  }

  const isMxValid = await hasValidMxRecord(domain);
  if (!isMxValid) {
    return { valid: false, reason: `No active mail server found for domain ${domain}` };
  }

  return { valid: true, reason: 'Valid syntax and active MX record' };
}

